package com.weatherapp.servlet;
import com.weatherapp.db.Database;import com.weatherapp.util.Json;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/api/public-cities") public class PublicCitiesServlet extends BaseServlet{protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{try{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT CityID,CityName,CountryCode FROM Cities WHERE IsActive=True ORDER BY CityName");ResultSet r=p.executeQuery()){while(r.next())a.add(Map.of("id",r.getInt(1),"name",r.getString(2),"country",r.getString(3)));}Json.write(res,a);}catch(Exception e){res.setStatus(500);Json.write(res,Map.of("message",e.getMessage()));}}}
